import { execFileSync } from "node:child_process";
import { crc32, deflateSync } from "node:zlib";
import { expect, test, type Locator, type Page } from "@playwright/test";
import { getPrismStudioDevCredentials } from "./dev-credentials";

/**
 * Phase 2G.3 Location View continuity on the REAL stack: Supabase Auth + RLS, the hosted Prism Studio database, the
 * real generation worker and PRIVATE Storage. MockProvider only: REAL IMAGE-MODEL CALLS 0, PAID CALLS 0. No 3D set.
 *
 *   upload Location View "Doorway" → Shot 4C chooses it → a free mock candidate is generated by the worker and its
 *   frozen request carries the view as `location_view` → conform → Use as Production Frame → Save as Location View
 *   "Doorway Tight" (same image) → both views persist. Everything created is removed afterwards.
 */
const { email: EMAIL, password: PASSWORD } = getPrismStudioDevCredentials();
const EP = "/projects/ojousama/episodes/ep-1";
const PLACE = "Sky-View Restaurant";
const PREFIX = `e2e-lv-${Date.now()}`;

test.describe.configure({ mode: "serial" });

function png(width: number, height: number, rgb: [number, number, number]): Buffer {
  const chunk = (type: string, data: Buffer) => {
    const len = Buffer.alloc(4);
    len.writeUInt32BE(data.length);
    const body = Buffer.concat([Buffer.from(type, "ascii"), data]);
    const crc = Buffer.alloc(4);
    crc.writeUInt32BE(crc32(body));
    return Buffer.concat([len, body, crc]);
  };
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8;
  ihdr[9] = 2;
  const raw = Buffer.alloc((width * 3 + 1) * height);
  for (let y = 0; y < height; y++)
    for (let x = 0; x < width; x++) raw.set(rgb, y * (width * 3 + 1) + 1 + x * 3);
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk("IHDR", ihdr),
    chunk("IDAT", deflateSync(raw)),
    chunk("IEND", Buffer.alloc(0)),
  ]);
}

const tsx = (script: string, args: string[]) =>
  execFileSync("npx", ["tsx", "--env-file=.env.local", script, ...args], {
    cwd: process.cwd(),
    env: {
      ...process.env,
      PRISM_STUDIO_PERSISTENCE: "supabase",
      PRISM_STUDIO_MOCK_STAGE_DELAY_MS: "0",
      NODE_ENV: "test",
      ...(process.env.PRISM_STUDIO_E2E_REAL_WORKER === "1"
        ? {}
        : { PRISM_STUDIO_WORKER_DEV_STORAGE: "1", PRISM_STUDIO_WORKER_DEV_ASSUME_ROLE: "1" }),
    },
    encoding: "utf8",
    timeout: 240_000,
    shell: process.platform === "win32",
  });

// mock attempts, the frames chosen from them and the views made of their images; then this test's own uploads (and
// the views of them). Both are scoped: real-provider history and anyone else's data are never touched.
const cleanup = () => {
  for (const [script, args] of [
    ["scripts/generation-cleanup.mts", ["--yes"]],
    ["scripts/previs-cleanup.mts", ["--yes", `--e2e-assets-prefix=${PREFIX}`]],
  ] as const) {
    try {
      tsx(script, [...args]);
    } catch {
      /* best effort; idempotent */
    }
  }
};
test.beforeAll(cleanup);
test.afterAll(cleanup);

async function signIn(page: Page) {
  await page.goto("/login");
  await page.getByLabel("Email").fill(EMAIL);
  await page.getByLabel("Password").fill(PASSWORD);
  await page.getByRole("button", { name: "Sign in" }).click();
  await expect(page.getByText("お嬢様、僕と結婚してください。").first()).toBeVisible({ timeout: 30_000 });
}

async function placeBlock(page: Page): Promise<Locator> {
  await page.goto("/projects/ojousama/locations");
  const block = page
    .locator("details")
    .filter({ has: page.locator("summary", { hasText: PLACE }) })
    .first();
  await block.locator("summary").first().click();
  return block;
}
const views = (scope: Locator) => scope.getByTestId("location-view-card");

test("hosted: upload view → Shot chooses it → worker generates with it → Production Frame → saved as a second view", async ({
  page,
}) => {
  test.setTimeout(480_000);
  await signIn(page);

  // ── Locations: upload "Doorway" (private Storage, 4:3, never cropped) ──
  let block = await placeBlock(page);
  await block.getByTestId("lv-upload").locator("summary").click();
  const form = block.getByTestId("lv-upload");
  await form.getByTestId("lv-upload-file").setInputFiles({
    name: `${PREFIX}-doorway.png`,
    mimeType: "image/png",
    buffer: png(400, 300, [120, 90, 60]),
  });
  await form.getByTestId("lv-upload-name").fill(`${PREFIX} Doorway`);
  await form.getByTestId("lv-upload-kind").selectOption("entrance");
  await form.getByTestId("lv-upload-viewpoint").fill("from the west entrance toward the window table");
  await form.getByTestId("lv-upload-submit").click();
  const doorway = views(block).filter({ hasText: `${PREFIX} Doorway` });
  await expect(doorway).toHaveCount(1, { timeout: 30_000 });
  const src = (await doorway.getByTestId("location-view-image").getAttribute("src"))!;
  expect(src).toMatch(/^\/api\/assets\/[0-9a-f-]{36}$/);
  await expect(doorway.getByTestId("location-view-image")).toHaveJSProperty("complete", true);
  expect(await page.content()).not.toMatch(/supabase\.co\/storage|createSignedUrl|token=/);

  // ── Shot Prep 4C: choose it (persisted in Postgres) ──
  await page.goto(`${EP}/shots`);
  const href = await page.getByRole("link", { name: "4C", exact: true }).first().getAttribute("href");
  const shotUrl = new URL(href!, "http://x").pathname;
  await page.goto(`${shotUrl}?section=production_frame`);
  const lv = page.getByTestId("location-view-section");
  await expect(lv.getByTestId("lv-location")).toHaveText(PLACE);
  await views(lv)
    .filter({ hasText: `${PREFIX} Doorway` })
    .getByTestId("lv-choose")
    .click();
  await expect(lv.getByTestId("lv-selected")).toContainText(`${PREFIX} Doorway`, { timeout: 30_000 });
  await page.reload();
  await expect(page.getByTestId("lv-selected")).toContainText(`${PREFIX} Doorway`);

  // ── generate one FREE mock candidate; the real worker process runs it ──
  const pf = page.getByTestId("production-frame-section");
  await pf.getByTestId("pf-generate-summary").click();
  const panel = pf.getByTestId("pf-candidates-panel");
  await expect(panel.getByTestId("pf-candidate-references")).toContainText(
    `Canonical Location View "${PREFIX} Doorway"`,
  );
  const row = panel.locator('[data-testid="model-row"][data-model="mock-image-wide"]');
  await expect(row.getByTestId("model-cost")).toContainText("free");
  await row.getByTestId("model-pick").check();
  await panel.getByTestId("ack-all").check();
  await panel.getByTestId("create-candidate-set").click();
  await page.waitForURL(/\/candidates\/[0-9a-f-]{36}/, { timeout: 90_000 });
  const setUrl = new URL(page.url()).pathname;
  const out = tsx("scripts/generation-worker.mts", ["--until-idle"]);
  expect(out).toContain("lyqdxiyjperhniwhzsvg");
  expect(out).not.toMatch(/service|password|postgres:\/\//i);
  await page.goto(setUrl);
  const card = page.locator('[data-testid="candidate-card"][data-model="mock-image-wide"]');
  await expect(card).toHaveAttribute("data-status", "succeeded", { timeout: 60_000 });
  // the frozen request (read back from Postgres) sent the view under its own role and label
  await expect(card.getByTestId("candidate-references")).toContainText(
    `Canonical Location View "${PREFIX} Doorway"`,
  );

  // ── conform → Use as Production Frame → Save as Location View ──
  await card.getByTestId("create-production-conform").click();
  await expect(card.getByTestId("use-as-pf")).toBeEnabled({ timeout: 120_000 });
  await card.getByTestId("use-as-pf").click();
  await expect(card.getByTestId("current-production-frame")).toBeVisible({ timeout: 60_000 });
  await page.goto(`${shotUrl}?section=production_frame`);
  await expect(pf.getByTestId("pf-selected")).toHaveAttribute("data-freshness", "fresh");
  const save = pf.getByTestId("pf-save-as-view");
  await save.locator("summary").click();
  await save.getByTestId("pf-view-name").fill(`${PREFIX} Doorway Tight`);
  await save.getByTestId("pf-view-kind").selectOption("entrance");
  await save.getByTestId("pf-save-as-view-submit").click();
  await expect(save).toContainText("Location View saved", { timeout: 30_000 });

  // ── both views persisted for the Location; the frame's view reuses the frame's image ──
  block = await placeBlock(page);
  await expect(views(block).filter({ hasText: PREFIX })).toHaveCount(2);
  const tight = views(block).filter({ hasText: `${PREFIX} Doorway Tight` });
  await expect(tight).toHaveAttribute("data-source", "production_frame");
  await page.goto(`${shotUrl}?section=production_frame`);
  const frameImg = (await page.getByTestId("pf-preview").getAttribute("src"))!;
  block = await placeBlock(page);
  expect(
    await views(block)
      .filter({ hasText: `${PREFIX} Doorway Tight` })
      .getByTestId("location-view-image")
      .getAttribute("src"),
  ).toBe(frameImg);
});
